def evidence(path,needle,role):
    raw=(ROOT/path).read_bytes()
    lines=raw.decode('utf-8-sig').splitlines()
    matches=[i+1 for i,v in enumerate(lines) if needle in v]
    if not matches:raise ValueError((path,needle))
    number=matches[0]
    return {'path':path,'line':number,'passage':lines[number-1].strip(),'role':role,'file_sha256':hashlib.sha256(raw).hexdigest()}

